  PeerConnection.RTCConfiguration rtcConfig=new PeerConnection.RTCConfiguration(new ArrayList<>(servers));
  rtcConfig.sdpSemantics=PeerConnection.SdpSemantics.UNIFIED_PLAN;
  for(PeerConnection pc:peers.values()){if(pc!=null)try{pc.setConfiguration(rtcConfig);}catch(Exception ignored){}}
